:root {
  --card-bg: #fefaf5;
  --card-border: #e8d9c4;
  --header-bg: #3b1f0e;
  --accent: #c1622a;
  --accent-light: #f5e6d8;
  --accent-muted: #e8a87c;
  --badge-bg: #c1622a;
  --badge-text: #ffffff;
  --stat-bg: #f5ece0;
  --stat-border: #e8d9c4;
  --stat-value: #3b1f0e;
  --stat-label: #9a7b5e;
  --step-bg: #fdf7f0;
  --step-border: #ecddc8;
  --step-done-bg: #eef7ee;
  --step-done-border: #b8ddb8;
  --step-done-num: #4a9e4a;
  --step-active-bg: #fff4eb;
  --step-active-border: #e8a87c;
  --step-active-num: #c1622a;
  --step-num-default: #b0956f;
  --step-name: #3b1f0e;
  --step-detail: #9a7b5e;
  --check-color: #4a9e4a;
  --pulse-color: #c1622a;
  --label-color: #9a7b5e;
  --bar-bg: #e8d9c4;
  --bar-fill: #c1622a;
  --btn-bg: #3b1f0e;
  --btn-text: #ffffff;
  --title-color: #ffffff;
  --subtitle-color: #d4a97a;
}

.brew-card {
  background: var(--card-bg);
  border: 1.5px solid var(--card-border);
  border-radius: 16px;
  width: 480px;
  padding: 0;
  overflow: hidden;
}

.brew-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
}

.brew-icon {
  font-size: 26px;
  line-height: 1;
}

.brew-title-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.brew-title {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  color: var(--title-color);
  line-height: 1.2;
}

.brew-subtitle {
  font-size: 12px;
  color: var(--subtitle-color);
  font-weight: 400;
}

.brew-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.brew-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-bottom: 1.5px solid var(--card-border);
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 8px;
  background: var(--stat-bg);
  border-right: 1px solid var(--stat-border);
  gap: 3px;
}

.stat:last-child {
  border-right: none;
}

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--stat-value);
  line-height: 1;
}

.stat-label {
  font-size: 11px;
  color: var(--stat-label);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.steps-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--label-color);
  text-transform: uppercase;
  letter-spacing: 0.8px;
  padding: 10px 18px 4px;
}

.steps {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 18px 12px;
}

.step {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--step-bg);
  border: 1px solid var(--step-border);
  border-radius: 10px;
  padding: 9px 12px;
}

.step.done {
  background: var(--step-done-bg);
  border-color: var(--step-done-border);
}

.step.active {
  background: var(--step-active-bg);
  border-color: var(--step-active-border);
}

.step-num {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-light);
  color: var(--step-num-default);
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.step.done .step-num {
  background: var(--step-done-bg);
  color: var(--step-done-num);
  border: 1.5px solid var(--step-done-border);
}

.step.active .step-num {
  background: var(--accent);
  color: #ffffff;
}

.step-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
}

.step-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--step-name);
  line-height: 1.2;
}

.step-detail {
  font-size: 11px;
  color: var(--step-detail);
}

.step-check {
  font-size: 14px;
  color: var(--check-color);
  font-weight: 700;
}

.step-pulse {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--pulse-color);
  flex-shrink: 0;
}

.brew-footer {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 18px 14px;
  border-top: 1.5px solid var(--card-border);
}

.ratio-bar-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
}

.ratio-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--label-color);
  text-transform: uppercase;
  letter-spacing: 0.4px;
  white-space: nowrap;
}

.ratio-bar {
  flex: 1;
  height: 6px;
  background: var(--bar-bg);
  border-radius: 4px;
  overflow: hidden;
}

.ratio-fill {
  width: 62%;
  height: 100%;
  background: var(--bar-fill);
  border-radius: 4px;
}

.ratio-tag {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent);
}

.brew-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 10px;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}
